var CART_KEY = "photo-portfolio-cart";

export function getCart() {
  try {
    var raw = localStorage.getItem(CART_KEY);
    var parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    console.warn("Failed to load cart from localStorage:", e);
    return [];
  }
}

export function setCart(items) {
  try {
    localStorage.setItem(CART_KEY, JSON.stringify(items));
    updateCartBadge();
  } catch (e) {
    console.error("Failed to save cart to localStorage:", e);
  }
}

export function addToCart(product, qty) {
  qty = qty == null ? 1 : Math.max(1, parseInt(qty, 10) || 1);
  var normalized = {
    id: String(product.id),
    title: product.title,
    priceCents: Number(product.priceCents) || 0,
    currency: product.currency || "USD",
    image: product.image || "",
  };
  var line = {
    id: normalized.id,
    title: normalized.title,
    priceCents: normalized.priceCents,
    currency: normalized.currency,
    image: normalized.image,
    qty: qty,
  };
  var cart = getCart();
  var found = cart.find(function (i) {
    return i.id === line.id;
  });
  if (found) {
    found.qty += qty;
  } else {
    cart.push(line);
  }
  setCart(cart);
  console.log("[addToCart]", line, "cart:", cart);
  return cart;
}

export function getCartCount() {
  return getCart().reduce(function (sum, i) {
    return sum + (i.qty || 0);
  }, 0);
}

